// Processamento OCR local no cliente sem backend intermediário
const extractTextFromImage = async (imageFile) => {
  const worker = await createWorker('por');
  const { data: { text } } = await worker.recognize(imageFile);
  await worker.terminate();
  return sanitizeInput(text);
};

// Detecção de queda real de preço e notificação imediata
async function evaluatePriceDrop(product, currentPrice) {
  const historicalAvg = await db.getAveragePrice(product.id);
  const discountPercent = ((historicalAvg - currentPrice) / historicalAvg) * 100;
  if (discountPercent >= 25) {
    await sendTelegramAlert(product, currentPrice, discountPercent);
  }
}

